.vp-doc [class*="language-"] > span.lang { color: var(--vp-c-text-2); }
.vp-doc [class*="language-"] code { font-size: 13px; line-height: 1.7; }
.vp-doc :not(pre) > code { overflow-wrap: anywhere; }
.vp-doc table { font-size: 14px; line-height: 1.6; }
.vp-doc th { background: var(--vp-c-bg-soft); font-size: 13px; font-weight: 600; text-align: left; }
.vp-doc td, .vp-doc th { padding: 12px 16px; }
.vp-doc tr:nth-child(2n) { background: transparent; }
.vp-doc .custom-block { border-radius: 8px; font-size: 14px; }
